"""Rule-based QC checks for autogenerated image/alt-text captions.

Catches placeholder captions, length outliers, and missing required
keywords before a caption ships. Does not look at the image itself.
"""
from __future__ import annotations

import argparse

BANNED_PHRASES = ["image of", "picture of", "no caption available", "untitled image"]
MIN_WORDS, MAX_WORDS = 3, 25


def check_caption(caption: str, required_keywords: list[str] | None = None) -> dict:
    required_keywords = required_keywords or []
    lowered = caption.lower()
    reasons = []
    word_count = len([w for w in caption.strip().split() if w])
    if word_count < MIN_WORDS:
        reasons.append("too_short")
    if word_count > MAX_WORDS:
        reasons.append("too_long")
    for phrase in BANNED_PHRASES:
        if phrase in lowered:
            reasons.append(f"banned_phrase:{phrase}")
    missing = [kw for kw in required_keywords if kw.lower() not in lowered]
    if missing:
        reasons.append("missing_keywords:" + ",".join(missing))
    return {"passed": not reasons, "reasons": reasons}


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("caption")
    parser.add_argument("--require", action="append", default=[], help="keyword that must appear (repeatable)")
    args = parser.parse_args()
    result = check_caption(args.caption, args.require)
    print("PASS" if result["passed"] else "FAIL: " + ", ".join(result["reasons"]))


if __name__ == "__main__":
    main()
